# Inverse of otbr-switch-update.sh: back to the always-on units, border router running. Feed to /bin/sh on stdin as root.
set -eu
H=/opt/usr/home/owner; UD=$H/.config/systemd/user; DATA=$H/apps_rw/com.samsung.tv.bixby-promotion/data
B=/opt/usr/share/quiet-tizen-backups/thread-border-router
usr(){ env HOME=$H XDG_RUNTIME_DIR=/run/user/5001 DBUS_SESSION_BUS_ADDRESS=kernel:path=/sys/fs/kdbus/5001-user/bus systemctl --user "$@"; }
[ "$(id -u)" = 0 ]
LBL=$(chsmack $H | sed 's/.*access="//; s/".*//')
for n in quiet-otbr-switch.path quiet-otbr-switch.service; do usr disable "$n" 2>/dev/null || true; usr stop "$n" 2>/dev/null || true; rm -f "$UD/default.target.wants/$n" "$UD/$n"; done
rm -f "$DATA/thread-off" "$DATA/thread-switch"
base64 -d > "$UD/quiet-otbr-cpcd.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-cpcd.service.new" | cut -d" " -f1)" = b46eebd0bcd872c5ed4ea44ef752dacce1505ce74d21197a6f79506ac84a3b59 ]
chown owner:users "$UD/quiet-otbr-cpcd.service.new"; chmod 644 "$UD/quiet-otbr-cpcd.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-cpcd.service.new"; mv "$UD/quiet-otbr-cpcd.service.new" "$UD/quiet-otbr-cpcd.service"
ln -sf ../quiet-otbr-cpcd.service "$UD/default.target.wants/quiet-otbr-cpcd.service"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-cpcd.service"
base64 -d > "$UD/quiet-otbr-agent.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-agent.service.new" | cut -d" " -f1)" = 89013bb11ceaa9a38e32ce227964008cadd1523cc7f7eb1cb4ae1c57fbc9b8be ]
chown owner:users "$UD/quiet-otbr-agent.service.new"; chmod 644 "$UD/quiet-otbr-agent.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-agent.service.new"; mv "$UD/quiet-otbr-agent.service.new" "$UD/quiet-otbr-agent.service"
ln -sf ../quiet-otbr-agent.service "$UD/default.target.wants/quiet-otbr-agent.service"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-agent.service"
base64 -d > "$UD/quiet-otbr-forward.service.new" <<'B64_EOF'

B64_EOF
[ "$(sha256sum "$UD/quiet-otbr-forward.service.new" | cut -d" " -f1)" = 4995d2c0a63fb47f8ace66564220261a59c9ab8581cc70c9a00292ab6319562a ]
chown owner:users "$UD/quiet-otbr-forward.service.new"; chmod 644 "$UD/quiet-otbr-forward.service.new"; chsmack -a "$LBL" "$UD/quiet-otbr-forward.service.new"; mv "$UD/quiet-otbr-forward.service.new" "$UD/quiet-otbr-forward.service"
ln -sf ../quiet-otbr-forward.service "$UD/default.target.wants/quiet-otbr-forward.service"; chown -h owner:users "$UD/default.target.wants/quiet-otbr-forward.service"
usr daemon-reload
usr start --no-block quiet-otbr-cpcd.service quiet-otbr-agent.service quiet-otbr-forward.service
for n in quiet-otbr-cpcd.service quiet-otbr-agent.service quiet-otbr-forward.service; do echo "$n: $(usr is-enabled $n)"; done
echo "RESTORED always-on units"
